/**
 * Centralized Roles, Permissions & Status Enums for Zibonbaba.com
 * Single Source of Truth across Customer, Seller, Reseller, Delivery, and Admin portals.
 */

// User Roles
export enum UserRole {
  SUPER_ADMIN = 'SUPER_ADMIN',
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  ACCOUNTANT = 'ACCOUNTANT',
  CUSTOMER_SUPPORT = 'CUSTOMER_SUPPORT',
  MARKETING = 'MARKETING',
  WAREHOUSE_MANAGER = 'WAREHOUSE_MANAGER',
  INVENTORY_MANAGER = 'INVENTORY_MANAGER',
  DELIVERY_MANAGER = 'DELIVERY_MANAGER',
  VENDOR_ADMIN = 'VENDOR_ADMIN',
  VENDOR_STAFF = 'VENDOR_STAFF',
  CUSTOMER = 'CUSTOMER',
  RESELLER = 'RESELLER',
  DELIVERY_MAN = 'DELIVERY_MAN'
}

// User Account Statuses
export enum AccountStatus {
  ACTIVE = 'ACTIVE',
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  VERIFIED = 'VERIFIED',
  SUSPENDED = 'SUSPENDED',
  BLOCKED = 'BLOCKED',
  REJECTED = 'REJECTED',
  DEACTIVATED = 'DEACTIVATED'
}

// Product Lifecycle Statuses
export enum ProductStatus {
  DRAFT = 'DRAFT',
  PENDING_APPROVAL = 'PENDING_APPROVAL',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED',
  ACTIVE = 'ACTIVE',
  INACTIVE = 'INACTIVE',
  OUT_OF_STOCK = 'OUT_OF_STOCK',
  ARCHIVED = 'ARCHIVED'
}

// Universal Order Statuses
export enum OrderStatus {
  PENDING = 'PENDING',
  CONFIRMED = 'CONFIRMED',
  PROCESSING = 'PROCESSING',
  SHIPPED = 'SHIPPED',
  READY_FOR_DELIVERY = 'READY_FOR_DELIVERY',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED',
  RETURNED = 'RETURNED',
  FAILED = 'FAILED'
}

// Universal Delivery Assignment Statuses
export enum DeliveryStatus {
  ASSIGNED = 'ASSIGNED',
  ACCEPTED = 'ACCEPTED',
  REJECTED = 'REJECTED',
  PICKED_UP = 'PICKED_UP',
  IN_TRANSIT = 'IN_TRANSIT',
  DELIVERED = 'DELIVERED',
  FAILED = 'FAILED',
  RETURNED = 'RETURNED'
}

// Payment Statuses
export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  FAILED = 'FAILED',
  REFUNDED = 'REFUNDED',
  PARTIALLY_REFUNDED = 'PARTIALLY_REFUNDED'
}

// Wallet Transaction Types
export enum TransactionType {
  CREDIT = 'CREDIT',
  DEBIT = 'DEBIT'
}

// Universal Withdrawal Request Statuses
export enum WithdrawalStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  PROCESSING = 'PROCESSING',
  COMPLETED = 'COMPLETED',
  REJECTED = 'REJECTED'
}

// Grouped Role Check Helpers
export const ADMIN_ROLES: string[] = [
  UserRole.SUPER_ADMIN,
  UserRole.ADMIN,
  UserRole.MANAGER,
  UserRole.ACCOUNTANT,
  UserRole.CUSTOMER_SUPPORT,
  UserRole.MARKETING,
  UserRole.WAREHOUSE_MANAGER,
  UserRole.INVENTORY_MANAGER,
  UserRole.DELIVERY_MANAGER
];

export const SELLER_ROLES: string[] = [
  UserRole.VENDOR_ADMIN,
  UserRole.VENDOR_STAFF,
  'SELLER'
];

export const RESELLER_ROLES: string[] = [
  UserRole.RESELLER
];

export const DELIVERY_ROLES: string[] = [
  UserRole.DELIVERY_MAN,
  'DELIVERYMAN',
  'COURIER',
  UserRole.DELIVERY_MANAGER
];

/**
 * Centralized State Machine for Zibonbaba.com
 * Validates legal state transitions for Orders and Delivery Assignments.
 */

import { OrderStatus, DeliveryStatus } from '@/lib/constants/roles';

// Legal transition map for Orders
export const ORDER_TRANSITIONS: Record<string, string[]> = {
  [OrderStatus.PENDING]: [OrderStatus.CONFIRMED, OrderStatus.CANCELLED],
  [OrderStatus.CONFIRMED]: [OrderStatus.PROCESSING, OrderStatus.CANCELLED],
  [OrderStatus.PROCESSING]: [OrderStatus.SHIPPED, OrderStatus.READY_FOR_DELIVERY, OrderStatus.CANCELLED],
  [OrderStatus.READY_FOR_DELIVERY]: [OrderStatus.SHIPPED, OrderStatus.CANCELLED],
  [OrderStatus.SHIPPED]: [OrderStatus.DELIVERED, OrderStatus.FAILED, OrderStatus.RETURNED],
  [OrderStatus.DELIVERED]: [OrderStatus.RETURNED],
  [OrderStatus.FAILED]: [OrderStatus.PROCESSING, OrderStatus.SHIPPED, OrderStatus.RETURNED, OrderStatus.CANCELLED],
  [OrderStatus.RETURNED]: [],
  [OrderStatus.CANCELLED]: []
};

// Legal transition map for Delivery Assignments
export const DELIVERY_TRANSITIONS: Record<string, string[]> = {
  [DeliveryStatus.ASSIGNED]: [DeliveryStatus.ACCEPTED, DeliveryStatus.REJECTED],
  [DeliveryStatus.ACCEPTED]: [DeliveryStatus.PICKED_UP, DeliveryStatus.REJECTED],
  [DeliveryStatus.PICKED_UP]: [DeliveryStatus.IN_TRANSIT, DeliveryStatus.FAILED],
  [DeliveryStatus.IN_TRANSIT]: [DeliveryStatus.DELIVERED, DeliveryStatus.FAILED, DeliveryStatus.RETURNED],
  [DeliveryStatus.FAILED]: [DeliveryStatus.IN_TRANSIT, DeliveryStatus.RETURNED],
  [DeliveryStatus.RETURNED]: [],
  [DeliveryStatus.REJECTED]: [DeliveryStatus.ASSIGNED],
  [DeliveryStatus.DELIVERED]: []
};

/**
 * Validates if an Order status transition is legally permitted.
 */
export function isValidOrderTransition(currentStatus: string, targetStatus: string): boolean {
  if (currentStatus === targetStatus) return true;
  const allowed = ORDER_TRANSITIONS[currentStatus.toUpperCase()];
  return Boolean(allowed && allowed.includes(targetStatus.toUpperCase()));
}

/**
 * Validates if a Delivery status transition is legally permitted.
 */
export function isValidDeliveryTransition(currentStatus: string, targetStatus: string): boolean {
  if (currentStatus === targetStatus) return true;
  const allowed = DELIVERY_TRANSITIONS[currentStatus.toUpperCase()];
  return Boolean(allowed && allowed.includes(targetStatus.toUpperCase()));
}

/**
 * Maps a Delivery Assignment status to the corresponding Order status.
 */
export function mapDeliveryToOrderStatus(deliveryStatus: string): string {
  switch (deliveryStatus.toUpperCase()) {
    case DeliveryStatus.ACCEPTED:
      return OrderStatus.PROCESSING;
    case DeliveryStatus.PICKED_UP:
    case DeliveryStatus.IN_TRANSIT:
      return OrderStatus.SHIPPED;
    case DeliveryStatus.DELIVERED:
      return OrderStatus.DELIVERED;
    case DeliveryStatus.FAILED:
      return OrderStatus.PROCESSING;
    case DeliveryStatus.RETURNED:
      return OrderStatus.CANCELLED;
    default:
      return OrderStatus.PROCESSING;
  }
}

/**
 * Centralized Cross-Portal Event & Notification Dispatcher for Zibonbaba.com
 */

import { prisma } from '@/lib/prisma';

export interface DispatchNotificationOptions {
  userId: string;
  title: string;
  body: string;
  type?: 'INFO' | 'SUCCESS' | 'WARNING' | 'ERROR';
  priority?: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'INFO';
  module?: 'MARKETPLACE' | 'ERP' | 'CRM' | 'HRM' | 'FINANCE' | 'SECURITY' | 'SUPPORT' | 'WALLET' | 'DELIVERY';
  link?: string;
  tx?: any; // Optional Prisma transaction client
}

/**
 * Creates an in-app notification for a user.
 */
export async function sendNotification(options: DispatchNotificationOptions): Promise<void> {
  const db = options.tx || prisma;
  try {
    await db.notification.create({
      data: {
        userId: options.userId,
        title: options.title,
        body: options.body,
        type: options.type || 'INFO',
        priority: options.priority || 'MEDIUM',
        module: options.module || 'MARKETPLACE',
        link: options.link || null
      }
    });
  } catch (err) {
    console.error('Failed to dispatch notification:', err);
  }
}

/**
 * Dispatches cross-portal notifications when an order status changes.
 */
export async function dispatchOrderStatusEvents(params: {
  orderId: string;
  newStatus: string;
  customerId?: string | null;
  sellerOwnerId?: string | null;
  resellerId?: string | null;
  deliveryManId?: string | null;
  orderNumber?: string;
  tx?: any;
}): Promise<void> {
  const {
    orderId,
    newStatus,
    customerId,
    sellerOwnerId,
    resellerId,
    deliveryManId,
    orderNumber = orderId.substring(0, 8).toUpperCase(),
    tx
  } = params;

  const db = tx || prisma;
  const statusUpper = newStatus.toUpperCase();

  // 1. Notify Customer
  if (customerId) {
    let customerTitle = `Order #${orderNumber} Status Updated`;
    let customerBody = `Your order is now ${statusUpper.toLowerCase()}.`;

    if (statusUpper === 'SHIPPED') {
      customerTitle = `Order #${orderNumber} is Shipped! 🚚`;
      customerBody = `Your order has been dispatched and is on its way.`;
    } else if (statusUpper === 'DELIVERED') {
      customerTitle = `Order #${orderNumber} Delivered! 🎉`;
      customerBody = `Your order has been successfully delivered. Thank you for shopping with Zibonbaba!`;
    }

    await sendNotification({
      userId: customerId,
      title: customerTitle,
      body: customerBody,
      type: statusUpper === 'DELIVERED' ? 'SUCCESS' : 'INFO',
      priority: statusUpper === 'DELIVERED' ? 'HIGH' : 'MEDIUM',
      module: 'MARKETPLACE',
      link: `/tracking?orderId=${orderId}`,
      tx: db
    });
  }

  // 2. Notify Seller
  if (sellerOwnerId) {
    await sendNotification({
      userId: sellerOwnerId,
      title: `Order #${orderNumber}: ${statusUpper}`,
      body: `Customer order #${orderNumber} is now marked as ${statusUpper}.`,
      type: 'INFO',
      priority: 'MEDIUM',
      module: 'ERP',
      link: `/seller/orders`,
      tx: db
    });
  }

  // 3. Notify Reseller
  if (resellerId) {
    await sendNotification({
      userId: resellerId,
      title: `Reseller Order #${orderNumber}: ${statusUpper}`,
      body: `Your customer order #${orderNumber} is now ${statusUpper}.`,
      type: statusUpper === 'DELIVERED' ? 'SUCCESS' : 'INFO',
      priority: statusUpper === 'DELIVERED' ? 'HIGH' : 'MEDIUM',
      module: 'WALLET',
      link: `/reseller/orders`,
      tx: db
    });
  }

  // 4. Notify Delivery Driver
  if (deliveryManId && statusUpper === 'ASSIGNED') {
    await sendNotification({
      userId: deliveryManId,
      title: `New Delivery Assignment! 🚴`,
      body: `You have been assigned order #${orderNumber}. Tap to view task details.`,
      type: 'INFO',
      priority: 'HIGH',
      module: 'DELIVERY',
      link: `/delivery`,
      tx: db
    });
  }
}

import { headers, cookies } from 'next/headers';
import { prisma } from '@/lib/prisma';
import jwt from 'jsonwebtoken';
import { ADMIN_ROLES, SELLER_ROLES, RESELLER_ROLES, DELIVERY_ROLES, AccountStatus } from '@/lib/constants/roles';

const JWT_SECRET = process.env.JWT_SECRET || 'zibonbaba_super_secure_jwt_session_secret_token_123';

export interface AuthUser {
  id: string;
  email: string;
  role: string;
  status?: string;
}

export interface SellerContext {
  user: AuthUser;
  store: {
    id: string;
    name: string;
    isApproved: boolean;
    commissionRate: number;
    ownerId: string;
  } | null;
  isPending: boolean;
}

/**
 * Extracts, verifies, and validates the JWT token from incoming Request headers or cookies.
 * Also verifies account active status.
 */
export async function getAuthUser(req?: Request): Promise<AuthUser | null> {
  let token: string | null = null;

  if (req) {
    const authHeader = req.headers.get('authorization') || req.headers.get('Authorization');
    if (authHeader && authHeader.startsWith('Bearer ')) {
      token = authHeader.substring(7).trim();
    }

    if (!token) {
      const cookieHeader = req.headers.get('cookie') || '';
      const match = cookieHeader.match(/zibonbaba_token=([^;]+)/);
      if (match) {
        token = decodeURIComponent(match[1]);
      }
    }
  }

  if (!token) {
    try {
      const cookieStore = await cookies();
      const cookieToken = cookieStore.get('zibonbaba_token')?.value;
      if (cookieToken) token = cookieToken;
    } catch (_) {}
  }

  if (!token) return null;

  try {
    const decoded = jwt.verify(token, JWT_SECRET) as any;
    if (decoded && decoded.id && decoded.email) {
      // Check database to ensure user is not suspended or deleted
      const dbUser = await prisma.user.findUnique({
        where: { id: decoded.id },
        select: { id: true, email: true, role: true, status: true }
      });

      if (!dbUser) return null;

      const userStatus = dbUser.status ? dbUser.status.toUpperCase() : 'ACTIVE';
      if (userStatus === AccountStatus.SUSPENDED || userStatus === AccountStatus.BLOCKED || userStatus === AccountStatus.DEACTIVATED) {
        return null; // Invalidate session for suspended or blocked users
      }

      return {
        id: dbUser.id,
        email: dbUser.email,
        role: dbUser.role.toUpperCase(),
        status: userStatus
      };
    }
  } catch (err) {
    return null;
  }

  return null;
}

export const ALL_ADMIN_ROLES = ADMIN_ROLES;

/**
 * Ensures the authenticated user has one of the allowed administrative roles.
 */
export async function requireAdminRole(
  req?: Request,
  allowedRoles: string[] = ADMIN_ROLES
): Promise<{ user: AuthUser | null; error: string | null; status: number }> {
  const user = await getAuthUser(req);

  if (!user) {
    return { user: null, error: 'Authentication required. Please log in to the admin portal.', status: 401 };
  }

  const normalizedRole = user.role.toUpperCase();
  const normalizedAllowed = allowedRoles.map(r => r.toUpperCase());

  if (!normalizedAllowed.includes(normalizedRole)) {
    return {
      user,
      error: `Access Denied. Role '${user.role}' is not authorized for administrative access.`,
      status: 403
    };
  }

  return { user, error: null, status: 200 };
}

/**
 * Ensures the authenticated user is a Seller (VENDOR_ADMIN or VENDOR_STAFF)
 * and retrieves their associated store context.
 */
export async function requireSeller(
  req?: Request
): Promise<{ context: SellerContext | null; error: string | null; status: number }> {
  const user = await getAuthUser(req);

  if (!user) {
    return { context: null, error: 'Authentication required. Please log in to the seller portal.', status: 401 };
  }

  const normalizedRole = user.role.toUpperCase();
  const sellerRoles = ['VENDOR_ADMIN', 'SELLER', 'VENDOR_STAFF', 'SUPER_ADMIN', 'ADMIN'];

  if (!sellerRoles.includes(normalizedRole)) {
    return {
      context: null,
      error: 'Access Denied. A seller account is required to access this resource.',
      status: 403
    };
  }

  // Find user's own store strictly by ownerId
  let store = await prisma.store.findFirst({
    where: { ownerId: user.id }
  });

  // If user is seller staff, find the store they belong to
  if (!store && normalizedRole === 'VENDOR_STAFF') {
    const staffMembership = await prisma.staffMember.findFirst({
      where: { userId: user.id, isActive: true },
      include: { seller: { include: { stores: true } } }
    });
    if (staffMembership?.seller?.stores?.[0]) {
      store = staffMembership.seller.stores[0];
    }
  }

  const isPending = store ? !store.isApproved : true;

  return {
    context: {
      user,
      store: store ? {
        id: store.id,
        name: store.name,
        isApproved: store.isApproved,
        commissionRate: store.commissionRate,
        ownerId: store.ownerId
      } : null,
      isPending
    },
    error: null,
    status: 200
  };
}

export interface ResellerContext {
  user: AuthUser;
  profile: any | null;
}

export interface DeliveryContext {
  user: AuthUser;
  profile: any | null;
}

/**
 * Ensures the authenticated user is a Reseller (or Admin).
 */
export async function requireReseller(
  req?: Request
): Promise<{ context: ResellerContext | null; error: string | null; status: number }> {
  const user = await getAuthUser(req);

  if (!user) {
    return { context: null, error: 'Authentication required. Please log in to the reseller portal.', status: 401 };
  }

  const normalizedRole = user.role.toUpperCase();
  const resellerRoles = ['RESELLER', 'SUPER_ADMIN', 'ADMIN'];

  if (!resellerRoles.includes(normalizedRole)) {
    return {
      context: null,
      error: 'Access Denied. A reseller account is required to access this resource.',
      status: 403
    };
  }

  let profile = await prisma.resellerProfile.findUnique({
    where: { userId: user.id }
  });

  if (!profile && normalizedRole === 'RESELLER') {
    profile = await prisma.resellerProfile.create({
      data: {
        userId: user.id,
        status: 'ACTIVE'
      }
    });
  }

  return {
    context: {
      user,
      profile
    },
    error: null,
    status: 200
  };
}

/**
 * Ensures the authenticated user is a Delivery Man / Courier (or Delivery Manager / Admin).
 */
export async function requireDeliveryMan(
  req?: Request
): Promise<{ context: DeliveryContext | null; error: string | null; status: number }> {
  const user = await getAuthUser(req);

  if (!user) {
    return { context: null, error: 'Authentication required. Please log in to the delivery partner portal.', status: 401 };
  }

  const normalizedRole = user.role.toUpperCase();
  const deliveryRoles = ['DELIVERY_MAN', 'COURIER', 'DELIVERY_MANAGER', 'SUPER_ADMIN', 'ADMIN'];

  if (!deliveryRoles.includes(normalizedRole)) {
    return {
      context: null,
      error: 'Access Denied. A delivery partner account is required to access this resource.',
      status: 403
    };
  }

  let profile = await prisma.deliveryProfile.findUnique({
    where: { userId: user.id }
  });

  if (!profile && (normalizedRole === 'DELIVERY_MAN' || normalizedRole === 'COURIER')) {
    profile = await prisma.deliveryProfile.create({
      data: {
        userId: user.id,
        status: 'APPROVED',
        availabilityStatus: 'OFFLINE'
      }
    });
  }

  return {
    context: {
      user,
      profile
    },
    error: null,
    status: 200
  };
}

/**
 * Ensures the authenticated user is logged in (Customer, Seller, Reseller, Delivery, or Admin).
 */
export async function requireCustomer(
  req?: Request
): Promise<{ user: AuthUser | null; error: string | null; status: number }> {
  const user = await getAuthUser(req);

  if (!user) {
    return { user: null, error: 'Authentication required. Please log in.', status: 401 };
  }

  return { user, error: null, status: 200 };
}

/**
 * Creates an immutable audit log entry in the database.
 */
export async function logAdminAction(
  userId: string | null,
  action: string,
  ipAddress: string | null = null
) {
  try {
    await prisma.auditLog.create({
      data: {
        userId,
        action,
        ipAddress
      }
    });
  } catch (err) {
    console.error('Audit Log Error:', err);
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { createClient } from '@supabase/supabase-js';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
const JWT_SECRET = process.env.JWT_SECRET || 'zibonbaba_super_secure_jwt_session_secret_token_123';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://ikocqacatdvhrameqeox.supabase.co';
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'sb_publishable_qC9hzMB61EWQLVH7flBdXA_GurkO2rd';

const supabase = createClient(supabaseUrl, supabaseAnonKey);

export async function POST(request: Request) {
  try {
    const { email, password } = await request.json();

    if (!email || !password) {
      return NextResponse.json({ error: 'Email and password are required.' }, { status: 400 });
    }

    const cleanInput = email.trim();
    const cleanEmail = cleanInput.toLowerCase();

    // 1. Check Prisma User Database by Email or Phone
    const user = await prisma.user.findFirst({
      where: {
        OR: [
          { email: cleanEmail },
          { phone: cleanInput },
          { phone: cleanInput.replace(/^\+880/, '0') },
          { phone: cleanInput.startsWith('0') ? `+88${cleanInput}` : cleanInput }
        ]
      },
      include: { profile: true, stores: true }
    });

    // 2. Also authenticate via Supabase Auth if email
    let supabaseAuthSuccess = false;
    if (cleanEmail.includes('@')) {
      try {
        const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
          email: cleanEmail,
          password
        });
        if (!authError && authData.user) {
          supabaseAuthSuccess = true;
        }
      } catch (_) {}
    }

    // 3. Password Verification (supports Prisma bcrypt hash & Supabase Auth)
    let isValidPassword = false;
    if (user) {
      isValidPassword = await bcrypt.compare(password, user.passwordHash);
    }

    if (!isValidPassword && !supabaseAuthSuccess) {
      return NextResponse.json({ error: 'Invalid credentials. Please check your email/phone and password.' }, { status: 401 });
    }

    if (user && (user.status === 'SUSPENDED' || user.status === 'BLOCKED')) {
      return NextResponse.json({ error: 'Account is suspended or blocked.' }, { status: 403 });
    }

    const payload = {
      id: user ? user.id : 'supa-user',
      email: user ? user.email : cleanEmail,
      role: user ? user.role : 'CUSTOMER'
    };

    const accessToken = jwt.sign(payload, JWT_SECRET, { expiresIn: '7d' });

    const primaryStore = user?.stores && user.stores.length > 0 ? user.stores[0] : null;

    const responseUser = {
      id: user ? user.id : 'supa-user',
      email: cleanEmail,
      role: user ? user.role : 'CUSTOMER',
      fullName: user?.profile?.fullName || cleanEmail.split('@')[0],
      avatar: user?.avatar || null
    };

    const userJson = encodeURIComponent(JSON.stringify(responseUser));

    const response = NextResponse.json(
      {
        message: 'Login successful.',
        accessToken,
        user: responseUser,
        store: primaryStore
      },
      { status: 200 }
    );

    response.cookies.set('zibonbaba_token', accessToken, { path: '/', httpOnly: true, sameSite: 'lax', maxAge: 604800 });
    response.cookies.set('zibonbaba_role', responseUser.role, { path: '/', sameSite: 'lax', maxAge: 604800 });
    response.cookies.set('zibonbaba_user', userJson, { path: '/', sameSite: 'lax', maxAge: 604800 });

    return response;
  } catch (err: any) {
    console.error('Auth Login API Error:', err);
    return NextResponse.json({ error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://ikocqacatdvhrameqeox.supabase.co';
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'sb_publishable_qC9hzMB61EWQLVH7flBdXA_GurkO2rd';
const supabase = createClient(supabaseUrl, supabaseAnonKey);

export async function POST(request: Request) {
  try {
    const formData = await request.formData();
    const file = formData.get('file') as File | null;
    const bucket = (formData.get('bucket') as string) || 'products';
    const customFolder = (formData.get('folder') as string) || 'uploads';

    if (!file) {
      return NextResponse.json({ error: 'No file provided' }, { status: 400 });
    }

    // Validate allowed buckets
    const allowedBuckets = ['products', 'avatars', 'stores', 'documents', 'banners'];
    const targetBucket = allowedBuckets.includes(bucket) ? bucket : 'products';

    // Generate unique safe file name
    const timestamp = Date.now();
    const randomStr = Math.random().toString(36).substring(2, 8);
    const sanitizedName = file.name.replace(/[^a-zA-Z0-9._-]/g, '_');
    const filePath = `${customFolder}/${timestamp}_${randomStr}_${sanitizedName}`;

    // Convert file to ArrayBuffer / Buffer for upload
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // Upload to Supabase Storage
    const { data, error } = await supabase.storage
      .from(targetBucket)
      .upload(filePath, buffer, {
        contentType: file.type || 'application/octet-stream',
        upsert: true,
      });

    if (error) {
      console.error('Supabase storage upload error:', error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    // Get public URL
    const { data: publicUrlData } = supabase.storage
      .from(targetBucket)
      .getPublicUrl(filePath);

    return NextResponse.json({
      success: true,
      url: publicUrlData.publicUrl,
      path: data.path,
      bucket: targetBucket,
      name: file.name,
      size: file.size,
      type: file.type,
    });
  } catch (err: any) {
    console.error('Upload API route error:', err);
    return NextResponse.json(
      { error: err.message || 'Internal server error during upload' },
      { status: 500 }
    );
  }
}

